import{z as i,x as B,o,c as n,q as t,j as A,D as e,d as r,s as d,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"DAX 与持久内存","description":"","frontmatter":{"title":"DAX 与持久内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dax-pmem.md","filePath":"cs/dax-pmem.md","lastUpdated":1791413859000}'),p={name:"cs/dax-pmem.md"};function c(D,a,m,f,C,h){const s=B("Mermaid");return o(),n("div",null,[a[2]||(a[2]=t('<h1 id="dax-与持久内存" tabindex="-1">DAX 与持久内存 <a class="header-anchor" href="#dax-与持久内存" aria-label="Permalink to &quot;DAX 与持久内存&quot;">​</a></h1><div class="epigraph"><p>DAX 让文件系统把持久内存页直接映进用户地址空间：load/store 代替 read/write，但持久顺序要靠刷写指令，而不是块层 flush。</p><footer>—— 据 Linux DAX 文档；Intel 对持久内存编程模型的说明；Rudoff 对 SNIA NVM 编程的整理</footer></div><p><a href="/cs/bcache">上一课</a>仍是块 I/O。<a href="/cs/fs-mmap-coherence">mmap</a> 通常缺页从块设备填 DRAM。<a href="/cs/nvme-driver">NVMe</a> 再快也是完成队列。缺口是 <strong>持久内存 + DAX</strong>：介质可字节寻址，页缓存变成可选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PMEM（或 CXL 内存的持久部分）出现在物理地址。FS（ext4/xfs dax、NOVA 等）可把文件映射到这些页，<code>MAP_SYNC</code> 等语义要求 store 到达持久点。缺口：CPU 缓存里的脏行不是持久的，需 <code>clwb</code>/<code>sfence</code> 或 <code>msync</code>；与 <a href="/cs/direct-io">O_DIRECT</a> 不同——没有 bio；与 tmpfs 不同——掉电还在（若刷对）。本课不把每一代 Optane 产品当目录。</p><p><span class="marginnote">可以想成图书馆借书：read/write 是管理员把书复印一份给你（来回两次拷贝，还要占页缓存）；DAX 是直接给你阅览室座位，书摊在面前，翻页就是 load/store——代价是合上书前，得自己把重要的页誊进保险柜（刷写到持久域）。</span></p><p><span class="marginnote">falloc 预分配在 DAX 上仍占介质。错误 DRAM 与 PMEM 混映射会把易失当持久。教学对象是「绕过块层的 mmap」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>挂载 <code>dax</code>：<code>mmap</code> 建立直接映射，fault 填物理 PMEM pfn。<code>read</code>/<code>write</code> 仍可走拷贝路径或短期缓冲。崩溃一致：应用或库（PMDK）按失败原子粒度刷。对照 <a href="/cs/cow-filesystem">COW FS</a>：仍可在 PMEM 上 COW，只是拷贝是 <code>memcpy</code> 加刷写。对照块设备：没有 mq-deadline。</p>',9)),(o(),A(l,null,{default:e(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MMAP%5B%22mmap%20DAX%22%5D%20--%3E%20PFN%5B%22%E6%8C%81%E4%B9%85%E5%86%85%E5%AD%98%E9%A1%B5%E5%B8%A7%22%5D%0A%20%20ST%5B%22store%22%5D%20--%3E%20CACHE%5B%22CPU%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20FLUSH%5B%22clwb%20%E7%AD%89%E5%88%B0%E6%8C%81%E4%B9%85%E5%9F%9F%22%5D%0A%20%20FLUSH%20--%3E%20MEDIA%5B%22PMEM%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"DAX 把存储栈变短：FS 负责分配与元数据，数据路径像内存。正确性从「bio 完成」换成「持久域可见性」，这是新的编程模型。不要把它写成量化超低延迟撮合。内核仍要管坏页、热插、fsck。",-1)),a[5]||(a[5]=E("p",null,"传统读与 DAX 读各经过哪些层：",-1)),(o(),A(l,null,{default:e(()=>[d(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BC%A0%E7%BB%9F%E8%AF%BB%EF%BC%9A%E5%BA%94%E7%94%A8%E8%B0%83%20read%22%5D%20--%3E%20B%5B%22VFS%20%E5%8A%A0%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%9D%97%E5%B1%82%E7%94%9F%E6%88%90%20bio%20%E8%AF%B7%E6%B1%82%22%5D%0A%20%20C%20--%3E%20D%5B%22%E9%A9%B1%E5%8A%A8%E5%8F%91%E8%B5%B7%EF%BC%8C%E4%B8%AD%E6%96%AD%E6%94%B6%E5%AE%8C%E6%88%90%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%8A%8A%E6%95%B0%E6%8D%AE%E6%8B%B7%E5%9B%9E%E7%94%A8%E6%88%B7%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%0A%20%20F%5B%22DAX%20%E8%AF%BB%EF%BC%9A%E5%BA%94%E7%94%A8%E7%9B%B4%E6%8E%A5%E8%AE%BF%E6%8C%87%E9%92%88%22%5D%20--%3E%20G%5B%22%E7%BC%BA%E9%A1%B5%E6%97%B6%20FS%20%E6%9F%A5%E5%88%B0%20PMEM%20%E7%9A%84%20pfn%22%5D%0A%20%20G%20--%3E%20H%5B%22%E9%A1%B5%E8%A1%A8%E7%9B%B4%E6%8E%A5%E6%8C%87%E5%90%91%E6%8C%81%E4%B9%85%E5%86%85%E5%AD%98%22%5D%0A%20%20H%20--%3E%20I%5B%22load%20%E7%9B%B4%E8%BE%BE%E4%BB%8B%E8%B4%A8%EF%BC%9A%E9%9B%B6%E6%8B%B7%E8%B4%9D%E3%80%81%E9%9B%B6%E4%B8%AD%E6%96%AD%E3%80%81%E6%97%A0%20bio%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">术语：「持久域」指掉电之后数据仍然完好的那一层。一条 store 通常只走到 CPU 缓存这层易失存储就「完成」了，所以必须再用 clwb 这类指令把缓存行往下推过持久域，写才算真正落袋——这就是「正确性换成持久域可见性」的意思。</span></p><p>与加密：dm-crypt 在块层，DAX 常绕过它，需 FS 级或硬件加密。</p><p>实现上：CPU 缓存行刷到持久域的指令因平台而异，库（PMDK）把这封装成粒度。混合 DRAM 缓存的 FSDAX 若崩溃，DRAM 里那一层不是持久的。 读法上只引用<a href="/cs/bcache">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>DAX 与持久内存</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 <code>pmem</code> 命名空间模式（fsdax vs devdax）。不保证每个平台的持久域边界文档一致。下一课回到块设备，但完成等待换成轮询：io polling。</p><p><span class="marginnote">初学者容易以为 DAX 下「store 写完 = 已经持久」。实际 store 落在 CPU 缓存就返回了，掉电即丢；必须按 PMDK 封装的粒度刷缓存行并加 fence。顺序同样要命：先刷数据、再刷指向它的元数据指针，反过来崩溃后就是一块悬空内存。</span></p><p>版本字段会变，课序钉的是机制对象「DAX 与持久内存」，不是某一主线内核的结构体名。 后课默认：PMEM 文件可 DAX 映射，持久靠刷写。块层用轮询代替中断收完成，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAX 把 PMEM 映进页表，绕过块层数据路径。</li><li>持久顺序是 CPU 刷写，不是 NVMe 完成。</li><li>轮询 I/O 是下一课。</li><li>出处：Linux DAX；SNIA NVM 模型；ext4/xfs dax 文档。</li></ul>',11))])}const u=i(p,[["render",c]]);export{P as __pageData,u as default};
